// All numeric coordinates below are illustration geometry. Specification values
// live in sheets.json; schematic dimensions never establish a product value.
function line(x1,y1,x2,y2,c='thin'){return mk('line',{x1,y1,x2,y2,class:c})}
function textLines(x,y,lines,c='svg-note',step=23){lines.forEach((s,i)=>tx(x,y+i*step,s,c))}
function noteBlock(rows){tx(52,62,'NOTES / 结构说明','nth');let y=96;rows.forEach((row,i)=>{nb(58,y-4,i+1);row.forEach((s,j)=>tx(78,y+j*22,s,'svg-note'));y+=row.length*22+17})}
function box(x,y,w,h,label,c='slot',r=2){rr(x,y,w,h,r,c);if(label)slotLabel(x,y,w,h,label)}
function cross(x,y,z){box(x,y,z,z,'','thin');line(x,y,x+z,y+z);line(x+z,y,x,y+z)}
function centerline(x,y,w,h){line(x-16,y+h/2,x+w+16,y+h/2,'cl')}
function tableFor(s){table(1180,100,'VARIABLES / 尺寸与待决策',s.vars);tx(1180,975,'代码仅在本图内有效 · [TBD] 不构成标准','dts')}
function caption(x,y,t,sub){title(x,y,t,sub)}
function introSheet(s){begin('sheet-'+s.id);tx(555,65,s.name+' / '+s.id.toUpperCase(),'sheet-head');tableFor(s)}
function layers(x,y,w,h,items){
 const k=.47,a=.94*k,b=.17*k,c=-.34*k,d=.47*k;
 items.forEach((label,i)=>{let z=i*40;let g=mk('g',{transform:`matrix(${a},${b},${c},${d},${x},${y-z})`});mk('rect',{x:0,y:0,width:w,height:h,rx:16,class:i===0?'thin':i===items.length-1?'slot':'obj','vector-effect':'non-scaling-stroke'},g);callout(x,y-z,x-65,y-z,label,-1)});
 caption(x+100,y+135,'LAYER STACK','比例示意 · 仅表示叠放顺序');
}
